// Tangkap pesan masuk dari mahasiswa
const userText = ($node["Telegram Trigger (Message)"].json.message.text || "").trim();
const chatId = $node["Telegram Trigger (Message)"].json.message.chat.id;

const raw = $input.first().json;
const data = raw.body || raw.data || raw;
const listDosen = data.lecturerDetails || [];

let replyText = "";

// Jika mahasiswa bertanya secara umum atau ketik /start atau /slot
if (userText === "/start" || userText === "/slot" || userText.toLowerCase().includes("slot") || userText.toLowerCase().includes("cek")) {
  replyText = `🤖 *BOT WAR DOSPEM PTI UNESA*\n\n🔍 *STATUS SISA SLOT DOSEN SAAT INI:*\n\n`;
  listDosen.forEach((dosen, i) => {
    const status = dosen.isFull ? "🔴 FULL" : `🟢 Sisa ${dosen.sisaSlot} Slot`;
    replyText += `${i + 1}. *${dosen.nama}*\n    Status: ${status} (${dosen.terisi}/${dosen.kuotaMax})\n\n`;
  });
  replyText += `💡 _Ketik nama dosen (contoh: Budi) untuk mencari sisa slot spesifik._`;
} else {
  // Cari dosen berdasarkan nama yang diketik mahasiswa
  const matched = listDosen.filter(d => d.nama.toLowerCase().includes(userText.toLowerCase()) || (d.nip && d.nip.includes(userText)));
  if (matched.length > 0) {
    replyText = `🔍 *HASIL PENCARIAN DOSEN ("${userText}"):*\n\n`;
    matched.forEach((dosen) => {
      const status = dosen.isFull ? "🔴 KUOTA FULL" : `🟢 SISA ${dosen.sisaSlot} SLOT`;
      replyText += `👨‍🏫 *${dosen.nama}*\n`;
      replyText += `   NIP: ${dosen.nip || "-"}\n`;
      replyText += `   Kuota: ${dosen.terisi} / ${dosen.kuotaMax} (${status})\n\n`;
    });
  } else {
    replyText = `❌ Dosen dengan kata kunci "*${userText}*" tidak ditemukan.\n\nKetik /slot untuk melihat seluruh daftar sisa slot dosen.`;
  }
}

return [{ json: { chatId, replyText } }];
